  'content.lenormand.26.keyword.1': 'Знание',
  'content.lenormand.26.keyword.2': 'Изучать',
  'content.lenormand.26.meaning': 'Скрытое знание — тайна, исследование или истина, еще не открытая свету.',
  'content.lenormand.26.combination.0': 'У Лисы секрет служит схеме.',
  'content.lenormand.26.combination.1': 'С Ключом секрет будет открыт.',
  'content.lenormand.26.combination.2': 'С Луной проявляется скрытая интуиция.',
  'content.lenormand.26.timing': 'Скрытое — раскрывается во времени',
