  'content.lenormand.9.keyword.0': 'Подарок',
  'content.lenormand.9.keyword.1': 'Милость',
  'content.lenormand.9.keyword.2': 'Признательность',
  'content.lenormand.9.meaning': 'Подарок, комплимент или красота, предложенные бесплатно — примите их, не рассчитывая цену.',
  'content.lenormand.9.combination.0': 'С Сердцем подарок становится привязанностью.',
  'content.lenormand.9.combination.1': 'С Солнцем приходит признание.',
  'content.lenormand.9.combination.2': 'С Кольцом — предложение преданности.',
  'content.lenormand.9.timing': 'Скоро — приятный сюрприз',
